// 3. Fallback resolver for all 23 constitutional languages
export function getRoleLoginTexts(langCode: string): RoleLoginTexts {
  if (ROLE_LOGIN_I18N[langCode]) {
    return ROLE_LOGIN_I18N[langCode];
  }
  // Regional script fallback: Eastern -> Bengali, Devanagari -> Hindi
  if (['as', 'mni'].includes(langCode)) {
    return ROLE_LOGIN_I18N['bn'] || ROLE_LOGIN_I18N['hi'];
  }
  if (['doi', 'kok', 'sa', 'ne'].includes(langCode)) {
    return ROLE_LOGIN_I18N['hi'];
  }
  return ROLE_LOGIN_I18N['hi'] || ROLE_LOGIN_I18N['en'];
}

export function getTaskTexts(langCode: string): TaskTexts {
  if (TASK_TEXTS_I18N[langCode]) {
    return TASK_TEXTS_I18N[langCode];
  }
  if (['as', 'mni'].includes(langCode)) {
    return TASK_TEXTS_I18N['bn'] || TASK_TEXTS_I18N['hi'];
  }
  if (['doi', 'kok', 'sa', 'ne'].includes(langCode)) {
    return TASK_TEXTS_I18N['hi'];
  }
  return TASK_TEXTS_I18N['hi'] || TASK_TEXTS_I18N['en'];
}


