export function getDoctorMobileTexts(langCode: string): DoctorMobileTexts {
  if (DOCTOR_MOBILE_I18N[langCode]) {
    return DOCTOR_MOBILE_I18N[langCode];
  }
  if (['as', 'mni'].includes(langCode)) {
    return DOCTOR_MOBILE_I18N['bn'] || DOCTOR_MOBILE_I18N['hi'];
  }
  if (['doi', 'kok', 'sa', 'ne'].includes(langCode)) {
    return DOCTOR_MOBILE_I18N['hi'];
  }
  return DOCTOR_MOBILE_I18N['hi'] || DOCTOR_MOBILE_I18N['en'];
}
